using System.Collections;
using System.Collections.Generic;
using System.IO;
using UnityEngine;
namespace CoopBeam {
// Opt-in only. Add at runtime; never save this component into a level.
public class ExpansionPlayModeQA:MonoBehaviour {
 List<string> lines=new List<string>();int passed,failed;GameManager game;LinkPowers powers;
 void Check(bool ok,string label){lines.Add((ok?"PASS ":"FAIL ")+label);if(ok)passed++;else failed++;}
 IEnumerator Start(){game=GameManager.Instance;powers=game.GetComponent<LinkPowers>();game.GetComponent<CandyLevelExit>().enabled=false;game.Begin();game.StopAllCoroutines();foreach(var h in game.players){h.Protect(2000);h.GetComponent<PlayerController2D>().enabled=false;h.GetComponent<Rigidbody2D>().bodyType=RigidbodyType2D.Kinematic;h.transform.position=new Vector3(h==game.players[0]?-10:10,5,0);}yield return null;
  Check(powers!=null,"Powers installed on active manager");Check(!powers.Confirm(0),"Empty ultimate cannot activate");powers.AddCharge(LinkPowers.ChargeRequired);Check(!powers.Confirm(0),"Both players must confirm");Check(powers.Confirm(1)&&powers.Ultimate,"Shared confirmation activates ultimate");Check(powers.Charge==0,"Ultimate consumes shared charge");powers.AddCharge(100);Check(powers.Charge==0,"Ultimate cannot recharge itself");
  powers.Collect(LinkPickup.Kind.Shield);Check(powers.Absorb(game.players[0]),"Shield absorbs one hit");Check(!powers.Absorb(game.players[0]),"Shield cannot absorb second hit");Check(powers.Absorb(game.players[1]),"Partner has independent shield");powers.Collect(LinkPickup.Kind.Prism);Check(powers.Empowered,"Prism widens cooperative link");
  var hazard=EncounterHazard.Spawn(new Vector2(0,3),Vector2.one,.75f,.5f,Vector2.zero,Color.cyan,this);Check(hazard&&!hazard.Active&&!hazard.GetComponent<Collider2D>().enabled,"Warning has no damaging collider");yield return new WaitForSeconds(.85f);Check(hazard&&hazard.Active&&hazard.GetComponent<Collider2D>().enabled,"Hazard collider activates after warning");yield return new WaitForSeconds(.6f);Check(!hazard,"Hazard expires");
  var collisionPlayer=Instantiate(game.players[0],new Vector3(0,3,0),Quaternion.identity);collisionPlayer.GetComponent<PlayerController2D>().enabled=false;collisionPlayer.GetComponent<Rigidbody2D>().bodyType=RigidbodyType2D.Kinematic;var collisionHazard=EncounterHazard.Spawn(new Vector2(0,3),Vector2.one,.3f,1,Vector2.zero,Color.cyan,this);yield return new WaitForSeconds(.15f);Check(collisionPlayer.Hearts==3,"Physical warning overlap does not remove hearts");yield return new WaitForSeconds(.4f);Check(collisionPlayer.Hearts==2,"Active physical overlap removes one heart");yield return new WaitForSeconds(.3f);Check(collisionPlayer.Hearts==2,"Invulnerability prevents repeated overlap damage");Destroy(collisionPlayer.gameObject);if(collisionHazard)collisionHazard.Clear();
  yield return new WaitForSeconds(2);var beam=FindAnyObjectByType<CoopBeam>();foreach(var enemy in game.enemies.ToArray())if(enemy)Destroy(enemy.gameObject);game.enemies.Clear();
  // All six roles run their real pattern coroutines. Player damage is suppressed for traversal.
  for(int role=0;role<6;role++){var e=Instantiate(game.enemyPrefabs[role],new Vector2(0,role==3?2:-3.6f),Quaternion.identity);game.enemies.Add(e);yield return null;var ai=e.GetComponent<IceEnemyBrain>();Check(ai!=null,"Role "+role+" brain assigned");float end=Time.time+6;while(e&&ai.AttacksPerformed==0&&Time.time<end)yield return null;Check(ai.AttacksPerformed>0,"Role "+role+" performs announced attack");e.FinishDeath();yield return new WaitForSeconds(.5f);}
  // Isolate ray accounting with overlapping colliders, including a zero-length segment.
  var dummy=Instantiate(game.enemyPrefabs[0],new Vector2(0,0),Quaternion.identity);game.enemies.Add(dummy);dummy.GetComponent<IceEnemyBrain>().enabled=false;dummy.GetComponent<Rigidbody2D>().bodyType=RigidbodyType2D.Kinematic;dummy.gameObject.AddComponent<BoxCollider2D>();yield return null;Physics2D.SyncTransforms();float hp=dummy.Health;beam.DamageSegment(new Vector2(-2,0),new Vector2(2,0),.1f);Check(Mathf.Abs(hp-dummy.Health-38*.1f*powers.DamageMultiplier)<.01f,"Multiple colliders and widened rays damage enemy only once");hp=dummy.Health;beam.DamageSegment(Vector2.zero,Vector2.zero,1);Check(dummy.Health==hp,"Overlapping players produce no ray damage");dummy.FinishDeath();yield return new WaitForSeconds(.5f);
  var bossEnemy=Instantiate(game.enemyPrefabs[6],new Vector2(0,-2.65f),Quaternion.identity);game.enemies.Add(bossEnemy);yield return null;var boss=bossEnemy.GetComponent<IceKingBoss>();float initial=bossEnemy.Health;bossEnemy.Damage(100);Check(bossEnemy.Health==initial,"Boss closed heart blocks damage");
  for(int phase=1;phase<=3;phase++){float deadline=Time.time+55;while(boss&&(!boss.Vulnerable||boss.Phase!=phase)&&Time.time<deadline)yield return null;Check(boss.Vulnerable&&boss.Phase==phase,"Boss phase "+phase+" offers recovery window");bossEnemy.Damage(100000);if(phase<3){Check(Mathf.Abs(bossEnemy.Health-bossEnemy.maxHealth*(phase==1?.68f:.34f))<.1f,"Cannot skip phase "+phase);yield return new WaitForSeconds(6.5f);Check(boss.Phase==phase+1,"Boss transforms to "+(phase+1));}else{Check(boss.Defeated,"Boss starts animated defeat");Check(game.enemies.Contains(bossEnemy),"Boss stays registered during defeat");yield return new WaitForSeconds(2.2f);Check(!game.enemies.Contains(bossEnemy),"Boss unregisters after animation");}}
  Check(EncounterHazard.LiveCount==0,"Boss defeat cleans owned hazards");Finish();
 }
 void Finish(){Time.timeScale=1;lines.Insert(0,"Expansion opt-in Play Mode QA: "+passed+" PASS, "+failed+" FAIL. Accelerated state traversal, not human difficulty certification.");File.WriteAllLines(Application.dataPath+"/ReinoDeHielo/0_6_QA/ExpansionPlayMode.txt",lines);Debug.Log("EXPANSION_QA_DONE "+passed+" PASS "+failed+" FAIL");}
 void OnDestroy(){Time.timeScale=1;}
}
}
